-- `SET NOT NULL` reads the rows, and the identity clause is accepted after it: the
-- column then draws from its sequence at the `START WITH`.
-- @setup
CREATE TABLE ai (c INT, v TEXT);
INSERT INTO ai VALUES (1, 'one'), (2, 'two');
ALTER TABLE ai ALTER COLUMN c SET NOT NULL;
ALTER TABLE ai ALTER COLUMN c ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 10);
INSERT INTO ai (v) VALUES ('minted');
-- @test
SELECT c, v FROM ai ORDER BY c;
